//! Public codec surface compiles and runs without selecting registry Candid.
use ic_platform::{
    Principal,
    candid_codec::{
        arguments::encode_args,
        decoder::{Arity, Limits, decode_args},
        encode_one,
    },
};

// Caller aliases must not capture names generated by Platform's macros.
type Result = ();
type Option = ();
const _: Result = ();
const _: Option = ();

#[derive(Debug, PartialEq)]
struct Record {
    a: Principal,
    b: Vec<u64>,
}
ic_platform::candid_record!(Record { 97 => a: Principal, 98 => b: Vec<u64> });
#[derive(Debug, PartialEq)]
enum State {
    A(Record),
    B(String),
}
ic_platform::candid_variant!(State { 65 => A(Record), 66 => B(String) });
fn limits() -> Limits {
    Limits {
        bytes: 4096,
        header: 1024,
        types: 64,
        work: 100_000,
        allocation: 16_384,
    }
}
#[test]
fn public_mappings_and_explicit_arguments() {
    let state = State::A(Record {
        a: Principal::from_slice(&[1]),
        b: vec![0, u64::MAX],
    });
    let bytes = encode_args(&(state, "message"), 4096).unwrap();
    let (actual, text): (State, String) = decode_args(&bytes, limits(), Arity::Exact).unwrap();
    assert_eq!(
        actual,
        State::A(Record {
            a: Principal::from_slice(&[1]),
            b: vec![0, u64::MAX]
        })
    );
    assert_eq!(text, "message");
    assert_eq!(
        encode_one(&42u64, 4096).unwrap(),
        b"DIDL\0\x01\x78\x2a\0\0\0\0\0\0\0"
    );
}

#[test]
#[cfg(feature = "nns-registry-types")]
fn registry_selection_uses_owned_codec() {
    use ic_platform::{nns_registry_types::GetSubnetForCanisterRequest, principal::Principal};
    let request = GetSubnetForCanisterRequest {
        principal: Some(Principal::anonymous()),
    };
    let bytes = encode_one(&request, 4096).unwrap();
    let (decoded,): (GetSubnetForCanisterRequest,) =
        decode_args(&bytes, limits(), Arity::Exact).unwrap();
    assert_eq!(decoded, request);
}

#[test]
#[cfg(feature = "icp-ledger-types")]
fn archive_reply_decodes_without_registry_candid() {
    use ic_platform::{icp_ledger_types::*, principal::Principal};
    let response = QueryEncodedBlocksResponse {
        certificate: None,
        blocks: vec![],
        chain_length: 1,
        first_block_index: 0,
        archived_blocks: vec![ArchivedEncodedBlocksRange {
            callback: QueryEncodedBlocksFn::new(Principal::anonymous(), "archive".into()),
            start: 0,
            length: 1,
        }],
    };
    let bytes = encode_one(&response, 4096).unwrap();
    let (actual,): (QueryEncodedBlocksResponse,) =
        decode_args(&bytes, limits(), Arity::Exact).unwrap();
    assert_eq!(actual, response);
}

// Consumer-selected limits are mappings, not a Platform product policy.
#[derive(Debug, PartialEq)]
struct Bounded<T, const N: usize>(Vec<T>);
impl<T: ic_platform::candid_codec::Encode, const N: usize> ic_platform::candid_codec::Encode
    for Bounded<T, N>
{
    const TYPE: &'static ic_platform::candid_codec::Type =
        <Vec<T> as ic_platform::candid_codec::Encode>::TYPE;
    fn write(
        &self,
        writer: &mut ic_platform::candid_codec::Writer,
    ) -> std::result::Result<(), ic_platform::candid_codec::Error> {
        self.0.write(writer)
    }
}
impl<'a, T: ic_platform::candid_codec::decoder::Decode<'a>, const N: usize>
    ic_platform::candid_codec::decoder::Decode<'a> for Bounded<T, N>
{
    fn read(
        reader: &mut ic_platform::candid_codec::decoder::Reader<'a>,
        wire: i64,
    ) -> std::result::Result<Self, ic_platform::candid_codec::decoder::Error> {
        reader.bounded_vec(wire, N).map(Self)
    }
}

#[test]
fn consumer_nested_caps_preserve_bytes_and_reject_before_decoding() {
    use ic_platform::candid_codec::decoder::{Error, decode_one_with_skip_limit};
    type Inventory = Bounded<Bounded<u8, 256>, 1024>;
    let values = vec![vec![9u8; 256]; 1024];
    let bytes = encode_one(&values, 1_000_000).unwrap();
    let budget = Limits {
        bytes: 1_000_000,
        header: 16384,
        types: 64,
        work: 2_097_152,
        allocation: 1_000_000,
    };
    let decoded = decode_one_with_skip_limit::<Inventory>(&bytes, budget, 0).unwrap();
    assert_eq!(encode_one(&decoded, 1_000_000).unwrap(), bytes);
    for excessive in [vec![vec![9u8; 257]], vec![Vec::<u8>::new(); 1025]] {
        let bytes = encode_one(&excessive, 1_000_000).unwrap();
        assert_eq!(
            decode_one_with_skip_limit::<Inventory>(&bytes, budget, 0),
            Err(Error::Limit)
        );
    }
}
